WITH lines AS (SELECT id, service, status_code, attr_key, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS attr_key, attr_value) SELECT attr_key, CASE WHEN status_code >= 452 THEN 'PREMIUM' ELSE 'STANDARD' END AS status_code_tier, SORT_ARRAY(COLLECT_SET(service)) AS service_list, COUNT(*) FILTER (WHERE attr_key = 'trace') AS trace_rows, ROUND(SUM(status_code) / NULLIF(COUNT(CASE WHEN service = 'search' THEN 1 END), 0), 2) AS status_code_per_search, MIN(status_code) AS min_status_code FROM lines GROUP BY attr_key, CASE WHEN status_code >= 452 THEN 'PREMIUM' ELSE 'STANDARD' END
